@import url(https://fonts.googleapis.com/css?family=Exo:100);

@keyframes bg-scrolling-reverse {
  from { background-position: 0 0; }
  to { background-position: 50px 50px; }
}

.bg-raw-custom {
  /* Usamos propiedades separadas para no bloquear la animación */
  background-image: url("data:image/png;base64,") !important;
  background-repeat: repeat !important;

  /* Esto activa el movimiento */
  animation: bg-scrolling-reverse 0.92s linear infinite !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

/* El texto INFINITY */
.bg-raw-custom::before {
  content: "INFINITY";
  font-family: 'Exo', sans-serif;
  font-size: 8rem;
  font-weight: 100;
  color: rgba(255,255,255,0.05);
  pointer-events: none;
}
